INSERT INTO "PreGeneratedQuestion" (id, "questionType", system, difficulty, "questionData", "questionOrder", "taskCategory", "validationStatus", "generatedAt")
VALUES
('q-tax-pulm-001', 'clinical-vignette', 'PULM', 'easy', '{"question":"A 68-year-old male with a 45 pack-year smoking history presents with chronic productive cough and dyspnea on exertion. He has been using albuterol inhalers for symptom relief. On examination, you note barrel chest and pursed-lip breathing. What is the most likely diagnosis?","options":["A. Emphysema","B. Chronic bronchitis","C. Asthma","D. Pulmonary fibrosis"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"The clinical presentation of barrel chest, pursed-lip breathing, and significant smoking history in a patient with predominantly dyspnea (rather than sputum production) is classic for emphysema. Emphysema is characterized by destruction of alveolar walls leading to loss of elastic recoil. Barrel chest results from chronic air trapping. Chronic bronchitis would present with prominent productive cough (3 months per year for 2+ years). Asthma typically presents acutely with reversible airflow obstruction, not this chronic presentation. Pulmonary fibrosis presents with restrictive, not obstructive, physiology.","conditionName":"Emphysema","system":"PULM","subcategory":"COPD","tags":["PULM","COPD","emphysema","smoking"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'diagnosis', 'pending', NOW()),
('q-tax-pulm-002', 'clinical-vignette', 'PULM', 'easy', '{"question":"A 55-year-old female smoker comes to clinic complaining of productive cough with yellow sputum for the past 4 months. She has had similar episodes for the past 3 years. Physical examination reveals coarse crackles at the bases bilaterally. What is the primary pathophysiology of her condition?","options":["A. Inflammation and hypersecretion of mucus in large airways","B. Destruction of alveolar walls and loss of elastic recoil","C. Reversible smooth muscle contraction in airways","D. Collagen deposition and pulmonary fibrosis"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"Chronic bronchitis is defined by productive cough occurring 3 months per year for at least 2 consecutive years, caused by inflammation and hypersecretion of mucus in the large airways. The yellow sputum indicates chronic inflammation. This patient meets diagnostic criteria with 4-month current episode in the context of 3-year history. Emphysema (choice B) is characterized by alveolar destruction. Asthma (choice C) involves reversible airway obstruction. Pulmonary fibrosis (choice D) involves collagen deposition.","conditionName":"Chronic Bronchitis","system":"PULM","subcategory":"COPD","tags":["PULM","COPD","chronic-bronchitis","sputum"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'history_pe', 'pending', NOW()),
('q-tax-pulm-003', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 62-year-old male with COPD (FEV1 35% predicted) is admitted with acute dyspnea, fever, and increased sputum production. Chest X-ray shows consolidation in the left lower lobe. He is a former smoker with 40 pack-years. Which organism is most likely responsible for this acute exacerbation?","options":["A. Streptococcus pneumoniae","B. Pseudomonas aeruginosa","C. Mycobacterium tuberculosis","D. Legionella pneumophila"],"correctAnswer":"B","correctAnswerIndex":1,"explanation":"In COPD patients with severe airflow obstruction (FEV1 <30% predicted), Pseudomonas aeruginosa is the most common cause of acute exacerbation with new consolidation. Pseudomonas is associated with more severe COPD, prior antibiotic use, and poor outcomes. Streptococcus pneumoniae is more common in mild-to-moderate COPD. Mycobacterium tuberculosis would present with more insidious symptoms, weight loss, and night sweats. Legionella presents with high fever, GI symptoms, and hyponatremia.","conditionName":"COPD Acute Exacerbation","system":"PULM","subcategory":"COPD","tags":["PULM","COPD","exacerbation","pseudomonas"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnosis', 'pending', NOW()),
('q-tax-pulm-004', 'clinical-vignette', 'PULM', 'easy', '{"question":"A 32-year-old female with a history of asthma since childhood presents to the ED with acute onset dyspnea, chest tightness, and cough after exposure to cat dander at a friend''s house. She has audible wheezing and uses rescue albuterol inhaler. Which finding is most consistent with acute asthma exacerbation?","options":["A. Decrease in peak expiratory flow","B. Increase in FEV1","C. Decreased total lung capacity","D. Increase in residual volume to normal levels"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"Acute asthma exacerbation causes airway narrowing and obstruction, leading to decreased peak expiratory flow (PEF). This is one of the objective measures of asthma severity. FEV1 decreases in asthma due to airway obstruction. Total lung capacity may increase (hyperinflation). Residual volume typically increases due to air trapping, not return to normal. Decreased PEF is a cardinal finding in asthma.","conditionName":"Asthma Exacerbation","system":"PULM","subcategory":"Asthma","tags":["PULM","asthma","exacerbation","wheeze"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'diagnostics', 'pending', NOW()),
('q-tax-pulm-005', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 28-year-old female with well-controlled asthma on inhaled corticosteroids presents with sudden onset of dyspnea and pleuritic chest pain while sitting at her desk. She has minimal cough and no wheezing. Vital signs: HR 110, RR 28, BP 118/76. Chest X-ray shows mediastinal shift and hyperlucency on the right side. What is the diagnosis?","options":["A. Acute asthma exacerbation","B. Pulmonary embolism","C. Pneumothorax","D. Spontaneous bacterial peritonitis"],"correctAnswer":"C","correctAnswerIndex":2,"explanation":"The clinical presentation of sudden dyspnea, pleuritic chest pain without prominent cough or wheezing, tachycardia, and CXR findings of mediastinal shift and hyperlucency on one side is classic for pneumothorax. Pneumothorax is not uncommon in young patients with asthma due to alveolar rupture (blebs). Acute asthma would have prominent wheezing. PE can present similarly but would not show hyperlucency. Spontaneous bacterial peritonitis is a peritoneal infection unrelated to pulmonary findings.","conditionName":"Pneumothorax","system":"PULM","subcategory":"Pneumothorax","tags":["PULM","pneumothorax","acute","chest-pain"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnosis', 'pending', NOW()),
('q-tax-pulm-006', 'clinical-vignette', 'PULM', 'hard', '{"question":"A 45-year-old male with asthma is hospitalized with severe acute exacerbation unresponsive to aggressive bronchodilator and corticosteroid therapy. ABG shows pH 7.28, pCO2 68, pO2 52 on high-flow oxygen. What is the primary mechanism of hypoxemia in this patient?","options":["A. Hypoventilation due to respiratory muscle fatigue","B. Ventilation-perfusion mismatch","C. Diffusion impairment","D. Right-to-left shunt"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"The elevated pCO2 (68) with respiratory acidosis indicates hypoventilation, meaning the primary mechanism is failure of ventilation due to respiratory muscle fatigue from severely increased work of breathing. While V/Q mismatch does contribute to hypoxemia in asthma exacerbation, the hypercapnia is the key finding indicating that the lungs cannot be adequately ventilated. This patient is approaching respiratory failure requiring intubation.","conditionName":"Severe Asthma Exacerbation","system":"PULM","subcategory":"Asthma","tags":["PULM","asthma","respiratory-failure","ABG"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'management', 'pending', NOW()),
('q-tax-pulm-007', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 42-year-old male presents with sudden onset pleuritic chest pain, dyspnea, and tachycardia. He returned from a cross-country flight 3 days ago. D-dimer is markedly elevated. CT pulmonary angiography shows a wedge-shaped area of increased density in the right lower lobe periphery. What is the underlying pathophysiology?","options":["A. Direct thromboembolism causing pulmonary infarction","B. Ventilation-perfusion mismatch from occlusion of pulmonary arteries","C. Aspiration pneumonia from prolonged immobility","D. Spontaneous pneumothorax from bullae rupture"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"The wedge-shaped peripheral consolidation (Hampton''s hump) is classic for pulmonary infarction, which occurs when a pulmonary embolus blocks a distal pulmonary artery. The infarction results from direct tissue damage from the thromboembolism itself. Risk factors include prolonged immobility from flight. While V/Q mismatch does occur in PE, the wedge-shaped infarction indicates tissue necrosis. Hampton''s hump appears in only 5-10% of PEs but when present is highly specific for infarction.","conditionName":"Pulmonary Embolism","system":"PULM","subcategory":"Pulmonary Embolism","tags":["PULM","PE","thromboembolism","infarction"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnosis', 'pending', NOW()),
('q-tax-pulm-008', 'clinical-vignette', 'PULM', 'hard', '{"question":"A 56-year-old female with recently diagnosed malignancy underwent chemotherapy 10 days ago. She now presents with acute dyspnea, pleuritic chest pain, hemoptysis, and tachycardia. BNP is elevated. Which mechanism best explains her clinical presentation?","options":["A. Hypercoagulability from malignancy and chemotherapy leading to PE","B. Acute decompensated heart failure from cardiotoxic chemotherapy","C. ARDS from sepsis and immunosuppression","D. Pneumonia from neutropenic infection"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"Malignancy causes a hypercoagulable state due to cancer cells activating tissue factor and expressing cancer procoagulant. Chemotherapy further increases thrombotic risk. The clinical presentation of acute dyspnea, pleuritic chest pain, hemoptysis, and tachycardia 10 days post-chemo is classic for PE. Elevated BNP can occur with PE due to right heart strain. While cardiotoxic chemotherapy can cause cardiomyopathy, the acute presentation with hemoptysis is more typical of PE.","conditionName":"Pulmonary Embolism - Cancer","system":"PULM","subcategory":"Pulmonary Embolism","tags":["PULM","PE","malignancy","hypercoagulability"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'diagnosis', 'pending', NOW()),
('q-tax-pulm-009', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 68-year-old male presents with dyspnea and orthopnea. Physical exam reveals decreased breath sounds bilaterally with dullness to percussion at the bases. Chest X-ray shows bilateral pleural effusions, cardiomegaly, and pulmonary edema. Which is the most likely diagnosis?","options":["A. Pleural effusion from tuberculosis","B. Exudative pleural effusion from malignancy","C. Transudative pleural effusion from congestive heart failure","D. Pneumoconiosis from occupational exposure"],"correctAnswer":"C","correctAnswerIndex":2,"explanation":"The clinical presentation of dyspnea, orthopnea, cardiomegaly, pulmonary edema, and bilateral pleural effusions is classic for congestive heart failure with transudative pleural effusions. Transudative effusions occur when normal Starling forces are altered, and are bilateral in 80% of CHF cases. TB effusions are typically unilateral. Malignant effusions are usually unilateral. Pneumoconiosis presents with parenchymal lung disease, not pleural effusions.","conditionName":"Pleural Effusion - CHF","system":"PULM","subcategory":"Pleural Effusion","tags":["PULM","pleural-effusion","CHF","transudative"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnosis', 'pending', NOW()),
('q-tax-pulm-010', 'clinical-vignette', 'PULM', 'hard', '{"question":"A 52-year-old female with breast cancer 2 years s/p mastectomy and radiation presents with unilateral pleural effusion on the right side (ipsilateral to radiation). Thoracentesis shows exudative fluid with negative cytology and cultures. Which diagnosis should be excluded first?","options":["A. Malignant pleural effusion","B. Post-radiation pleural effusion","C. Parapneumonic effusion","D. Tuberculosis"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"While post-radiation pleural effusion can occur years after chest wall/lung radiation, malignancy must always be excluded first in a cancer patient with pleural effusion. Negative cytology does not completely rule out malignancy (sensitivity only 60-80% on first tap). Additional testing such as pleural biopsy, repeat thoracentesis, or imaging should be pursued. The ipsilateral location to prior radiation makes post-radiation effusion reasonable, but malignancy is the priority diagnosis to exclude.","conditionName":"Pleural Effusion - Malignancy","system":"PULM","subcategory":"Pleural Effusion","tags":["PULM","pleural-effusion","malignancy","exudate"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'diagnostics', 'pending', NOW()),
('q-tax-pulm-011', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 35-year-old previously healthy male presents to the ICU with acute dyspnea, diffuse crackles, and hypoxemia refractory to supplemental oxygen. He had a seizure 2 days ago. Chest X-ray shows bilateral infiltrates. Vitals show tachycardia and tachypnea. What is the most likely diagnosis?","options":["A. Pulmonary edema from seizure-induced hypertension","B. Acute respiratory distress syndrome","C. Aspiration pneumonia from impaired consciousness","D. Acute coronary syndrome with pulmonary edema"],"correctAnswer":"B","correctAnswerIndex":1,"explanation":"The acute onset respiratory failure with bilateral infiltrates and hypoxemia refractory to supplemental oxygen in a patient with recent seizure is consistent with ARDS. ARDS criteria require: acute onset, bilateral infiltrates on imaging, hypoxemia (PaO2/FiO2 ratio), and absence of cardiogenic cause. Post-seizure aspiration can precipitate ARDS. While pulmonary edema from seizure-induced hypertension can occur acutely, refractory hypoxemia is more typical of ARDS.","conditionName":"ARDS","system":"PULM","subcategory":"ARDS","tags":["PULM","ARDS","respiratory-failure","bilateral-infiltrates"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnosis', 'pending', NOW()),
('q-tax-pulm-012', 'clinical-vignette', 'PULM', 'hard', '{"question":"A 48-year-old male with sepsis from pneumonia develops progressive hypoxemia and bilateral infiltrates despite appropriate antibiotics and mechanical ventilation. His lung compliance is markedly decreased and he requires high PEEP and FiO2. What is the primary pathophysiologic process occurring in his lungs?","options":["A. Surfactant depletion and alveolar collapse","B. Smooth muscle contraction from bronchoconstriction","C. Bacterial invasion and pulmonary abscess formation","D. Allergic bronchospasm and airway edema"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"ARDS involves diffuse alveolar-capillary injury leading to increased permeability, protein-rich edema, surfactant depletion, and formation of hyaline membranes. Surfactant depletion contributes to alveolar collapse and decreased compliance, requiring high PEEP and FiO2. Type II pneumocytes are damaged in ARDS. Bronchoconstriction would cause obstructive physiology with air-trapping, not this restrictive pattern. Abscess formation and allergic bronchospasm are not features of ARDS.","conditionName":"ARDS","system":"PULM","subcategory":"ARDS","tags":["PULM","ARDS","surfactant","alveolar-injury"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'basic_science', 'pending', NOW()),
('q-tax-pulm-013', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 62-year-old male with 60 pack-year smoking history presents with hemoptysis, hoarseness, and weight loss over 2 months. He also notes right shoulder pain. Chest X-ray shows a central right upper lobe mass. What is the most likely diagnosis?","options":["A. Small cell lung cancer with brain metastases","B. Non-small cell lung cancer with Pancoast syndrome","C. Squamous cell carcinoma of the trachea","D. Tuberculosis with cavitary disease"],"correctAnswer":"B","correctAnswerIndex":1,"explanation":"The combination of smoking history, hemoptysis, weight loss, right upper lobe mass, and right shoulder pain is classic for Pancoast syndrome (superior pulmonary sulcus tumor). Pancoast tumors are typically non-small cell lung cancers (often squamous cell) that invade the apical pleura and brachial plexus, causing referred pain. Hoarseness can result from recurrent laryngeal nerve involvement. SCLC is more associated with brain metastases. TB would have more insidious onset with night sweats.","conditionName":"Lung Cancer - Non-Small Cell","system":"PULM","subcategory":"Lung Cancer","tags":["PULM","lung-cancer","pancoast","smoking"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'history_pe', 'pending', NOW()),
('q-tax-pulm-014', 'clinical-vignette', 'PULM', 'hard', '{"question":"A 58-year-old female with a smoking history presents with cough and dyspnea. CT chest shows a 3 cm right upper lobe nodule with irregular borders and hilar lymphadenopathy. Which medication class is now part of first-line therapy for her presumed advanced non-small cell lung cancer?","options":["A. Histone deacetylase inhibitors","B. Programmed death ligand-1 (PD-L1) inhibitors","C. Tyrosine kinase inhibitors for EGF receptor mutations","D. Vinca alkaloid chemotherapy agents"],"correctAnswer":"B","correctAnswerIndex":1,"explanation":"PD-L1 inhibitors (checkpoint inhibitors) have become standard first-line therapy for advanced NSCLC without targetable mutations, often combined with chemotherapy. These agents block the PD-1/PD-L1 pathway, allowing T cells to recognize and attack cancer cells. HDAC inhibitors have limited role in NSCLC. EGFR tyrosine kinase inhibitors are first-line only for NSCLC with EGFR mutations (about 15% of patients). Vinca alkaloids are older chemotherapy rarely used as monotherapy.","conditionName":"Lung Cancer - Non-Small Cell Advanced","system":"PULM","subcategory":"Lung Cancer","tags":["PULM","lung-cancer","immunotherapy","PD-L1"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'pharmaceutical', 'pending', NOW()),
('q-tax-pulm-015', 'clinical-vignette', 'PULM', 'easy', '{"question":"A 56-year-old obese male reports daytime somnolence, loud snoring, and his wife notes he stops breathing at night. He has hypertension treated with one medication. What sleep-related disorder is most likely?","options":["A. Narcolepsy","B. Obstructive sleep apnea","C. Restless leg syndrome","D. REM sleep behavior disorder"],"correctAnswer":"B","correctAnswerIndex":1,"explanation":"The classic presentation of obstructive sleep apnea includes loud snoring, witnessed apneic episodes, daytime somnolence, and obesity. OSA is very common in obese males. The association with hypertension is also typical, as OSA is a major risk factor for hypertension. Narcolepsy presents with sudden sleep attacks and cataplexy. Restless leg syndrome involves uncomfortable sensations and urge to move legs. REM sleep behavior disorder involves acting out dreams.","conditionName":"Obstructive Sleep Apnea","system":"PULM","subcategory":"Sleep Disorders","tags":["PULM","OSA","sleep-apnea","snoring"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'history_pe', 'pending', NOW()),
('q-tax-pulm-016', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 64-year-old female smoker presents with dyspnea on exertion and exertional syncope. She has orthostatic hypotension and a loud P2 component on heart sounds. Echocardiography shows severe right ventricular dilatation and elevated RV systolic pressure. What chronic pulmonary disease most likely led to these findings?","options":["A. Pulmonary hypertension from chronic hypoxia due to COPD","B. Acute myocardial infarction with cardiomyopathy","C. Mitral stenosis causing secondary pulmonary hypertension","D. Atrial septal defect with right-to-left shunting"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"Chronic COPD causes chronic hypoxemia, which leads to pulmonary vasoconstriction and pulmonary hypertension over time. This develops into cor pulmonale (right heart failure from pulmonary disease). The findings of RV dilatation, elevated RV systolic pressure, loud P2, and syncope from RV dysfunction fit cor pulmonale from chronic hypoxemia. Smoking and COPD are typical risk factors. While mitral stenosis can cause pulmonary hypertension, the described RV dysfunction pattern is more typical of chronic hypoxic disease.","conditionName":"Cor Pulmonale","system":"PULM","subcategory":"Cor Pulmonale","tags":["PULM","cor-pulmonale","pulmonary-hypertension","COPD"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnosis', 'pending', NOW()),
('q-tax-pulm-017', 'clinical-vignette', 'PULM', 'hard', '{"question":"A 45-year-old female with progressive dyspnea and restrictive spirometry (FVC and FEV1 both reduced proportionally) has presented for 6 years with bilateral fine crackles at end-inspiration. High-resolution CT shows reticular opacities and traction bronchiectasis. Which finding would most support idiopathic pulmonary fibrosis over other interstitial lung diseases?","options":["A. Positive rheumatoid factor and anti-CCP antibodies","B. Usual interstitial pneumonia (UIP) pattern on HRCT with honeycombing","C. Elevated angiotensin-converting enzyme (ACE) level and hypercalcemia","D. Exposure history to asbestos or silica dust"],"correctAnswer":"B","correctAnswerIndex":1,"explanation":"Idiopathic pulmonary fibrosis is defined by a UIP pattern on HRCT showing architectural distortion with honeycombing, traction bronchiectasis, and reticular opacities predominantly in the lower lobes and peripheral zones. This HRCT pattern in the appropriate clinical context is diagnostic or supports diagnosis of IPF. Positive rheumatoid factor suggests connective tissue disease-related ILD. Elevated ACE suggests sarcoidosis. Exposure history suggests occupational/environmental ILD.","conditionName":"Pulmonary Fibrosis","system":"PULM","subcategory":"Interstitial Lung Disease","tags":["PULM","pulmonary-fibrosis","IPF","UIP"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'diagnostics', 'pending', NOW()),
('q-tax-pulm-018', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 28-year-old with cystic fibrosis presents with acute dyspnea, fever, and green sputum. Sputum culture grows Pseudomonas aeruginosa. Which medication class is used to treat CF-related pulmonary infections with Pseudomonas?","options":["A. Macrolide antibiotics (azithromycin)","B. Fluoroquinolone antibiotics (ciprofloxacin) and beta-lactams (piperacillin-tazobactam)","C. Trimethoprim-sulfamethoxazole","D. Vancomycin only"],"correctAnswer":"B","correctAnswerIndex":1,"explanation":"CF lung infections with Pseudomonas aeruginosa require aggressive anti-Pseudomonas therapy, typically with a fluoroquinolone (like ciprofloxacin) combined with an inhaled anti-Pseudomonas agent or IV beta-lactam (like piperacillin-tazobactam or ceftazidime). Macrolides like azithromycin have immunomodulatory effects and may be used chronically in CF but are not first-line for acute infection. TMP-SMX and vancomycin alone do not provide adequate Pseudomonas coverage.","conditionName":"Cystic Fibrosis","system":"PULM","subcategory":"Genetic/Metabolic Lung Disease","tags":["PULM","cystic-fibrosis","pseudomonas","infection"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'pharmaceutical', 'pending', NOW()),
('q-tax-pulm-019', 'clinical-vignette', 'PULM', 'easy', '{"question":"A 32-year-old female with cystic fibrosis has chronic airway colonization with Pseudomonas and undergoes chronic inhaled tobramycin therapy. Which mechanism of action explains tobramycin''s effectiveness in CF lung disease?","options":["A. Disruption of bacterial cell wall synthesis","B. Inhibition of bacterial protein synthesis","C. Direct anti-inflammatory action","D. Restoration of CFTR channel function"],"correctAnswer":"B","correctAnswerIndex":1,"explanation":"Tobramycin is an aminoglycoside antibiotic that inhibits bacterial protein synthesis by binding to the 30S ribosomal subunit. Inhaled tobramycin is used chronically in CF patients with Pseudomonas colonization. While tobramycin''s primary mechanism is antimicrobial, it may also reduce bacterial burden and associated inflammation. Beta-lactams disrupt cell wall synthesis. Choice C is a secondary benefit. Choice D is not relevant to tobramycin.","conditionName":"Cystic Fibrosis","system":"PULM","subcategory":"Genetic/Metabolic Lung Disease","tags":["PULM","cystic-fibrosis","tobramycin","aminoglycoside"],"generatedWith":"taxonomy-gen-v1"}', 'first', 'basic_science', 'pending', NOW()),
('q-tax-pulm-020', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 42-year-old with cough, dyspnea, and systemic symptoms presents with bilateral hilar lymphadenopathy and erythema nodosum on examination. Serum ACE level is elevated and serum calcium is high. What is the most likely diagnosis?","options":["A. Tuberculosis","B. Histoplasmosis","C. Sarcoidosis","D. Lymphoma"],"correctAnswer":"C","correctAnswerIndex":2,"explanation":"Sarcoidosis classically presents with bilateral hilar lymphadenopathy, systemic symptoms, and constitutional findings like erythema nodosum. The elevated ACE level and hypercalcemia are typical laboratory findings in sarcoidosis, caused by activated macrophages and granulomas producing calcitriol. While TB and histoplasmosis can present similarly, they do not typically cause hypercalcemia and elevated ACE as primary features. Lymphoma would not explain the elevated ACE level.","conditionName":"Sarcoidosis","system":"PULM","subcategory":"Granulomatous Lung Disease","tags":["PULM","sarcoidosis","granuloma","ACE"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnosis', 'pending', NOW()),
('q-tax-pulm-021', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 48-year-old with TB infection completed standard 4-month directly observed therapy (RIPE: rifampin, isoniazid, pyrazinamide, ethambutol) 3 months ago. He now presents with fever, night sweats, and productive cough with hemoptysis. What is the most likely diagnosis?","options":["A. Drug-resistant tuberculosis (treatment failure)","B. Recurrent TB from poor medication adherence","C. Aspergilloma development in old TB cavitary disease","D. Active tuberculosis from new exposure"],"correctAnswer":"C","correctAnswerIndex":2,"explanation":"Following successful TB treatment, hemoptysis and recurrent respiratory symptoms can result from aspergilloma (fungal ball) developing in residual cavitary disease. Aspergillus colonizes old TB cavities, forming a fungal ball that can cause hemoptysis. This is a late complication distinct from treatment failure or recurrent TB. While resistance or new exposure are possible, the 3-month post-treatment timeline with hemoptysis and cavitary disease history makes aspergilloma most likely.","conditionName":"Tuberculosis - Aspergilloma Complication","system":"PULM","subcategory":"Tuberculosis","tags":["PULM","TB","aspergilloma","hemoptysis"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'management', 'pending', NOW()),
('q-tax-pulm-022', 'clinical-vignette', 'PULM', 'hard', '{"question":"A 35-year-old immigrant from India presents with chronic cough, low-grade fever, and weight loss. Sputum smear shows acid-fast bacilli. He is started on standard TB therapy with rifampin, isoniazid, pyrazinamide, and ethambutol. At week 4, he develops acute liver injury (transaminases 5x normal) and jaundice. Which agent is most likely responsible?","options":["A. Ethambutol causing hepatotoxicity","B. Isoniazid causing drug-induced liver injury (DILI)","C. Rifampin causing DILI through impaired liver synthetic function","D. Pyrazinamide causing hepatotoxicity"],"correctAnswer":"D","correctAnswerIndex":3,"explanation":"Pyrazinamide is hepatotoxic and causes drug-induced liver injury in 1-3% of patients, usually within the first 4-8 weeks of therapy. This occurs more commonly in patients with baseline liver disease or poor acetylator status. Elevated transaminases and jaundice at week 4 fit pyrazinamide hepatotoxicity. While isoniazid can cause DILI, it is less common and the acute timing fits pyrazinamide better. Rifampin rarely causes hepatotoxicity. Ethambutol''s primary toxicity is optic neuritis. If hepatotoxicity is suspected, pyrazinamide should be discontinued.","conditionName":"Tuberculosis - Drug-Induced Liver Injury","system":"PULM","subcategory":"Tuberculosis","tags":["PULM","TB","hepatotoxicity","pyrazinamide","DILI"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'pharmaceutical', 'pending', NOW()),
('q-tax-pulm-023', 'clinical-vignette', 'PULM', 'medium', '{"question":"A 38-year-old male with recurrent lung infections and chronic productive cough presents with purulent sputum and CT findings of dilated airways with bronchus-to-artery ratio >1. Sputum culture grows Haemophilus influenzae. What is the diagnosis?","options":["A. Chronic bronchitis","B. Asthma with chronic infection","C. Bronchiectasis","D. Cystic fibrosis"],"correctAnswer":"C","correctAnswerIndex":2,"explanation":"Bronchiectasis is defined by irreversible airway dilation with bronchus-to-artery ratio >1 on CT imaging. It presents with chronic productive cough, recurrent infections, and hemoptysis. The dilated airways fail to clear secretions, leading to bacterial colonization. Common organisms include H. influenzae and P. aeruginosa. While chronic bronchitis causes productive cough, it does not show structural airway dilation. CF is a genetic disease, not an acquired condition. This patient likely has post-infectious or post-TB bronchiectasis.","conditionName":"Bronchiectasis","system":"PULM","subcategory":"Chronic Airways Disease","tags":["PULM","bronchiectasis","dilated-airways","recurrent-infection"],"generatedWith":"taxonomy-gen-v1"}', 'second', 'diagnostics', 'pending', NOW()),
('q-tax-pulm-024', 'clinical-vignette', 'PULM', 'hard', '{"question":"A 52-year-old with COPD and a 3 cm right lower lobe nodule is undergoing evaluation for possible lung cancer. His FEV1 is 28% predicted. Before proceeding with lung cancer surgery, what is the most important consideration?","options":["A. Screen for brain metastases with MRI brain","B. Assess his ability to tolerate surgery and chemotherapy given severe airflow obstruction","C. Perform PET-CT for staging","D. Confirm nodule etiology with biopsy"],"correctAnswer":"B","correctAnswerIndex":1,"explanation":"In a patient with severe COPD (FEV1 28%), assessing surgical tolerance and cardiopulmonary reserve is critical before committing to lung cancer treatment. Severe airflow obstruction increases perioperative morbidity and mortality. An FEV1 <1.0 L is concerning for increased surgical risk. Pulmonary function testing, cardiopulmonary exercise testing, and careful preoperative assessment are needed. While staging and confirmation are important, functional assessment takes priority in this high-risk patient.","conditionName":"Lung Cancer - Perioperative Assessment","system":"PULM","subcategory":"Lung Cancer","tags":["PULM","lung-cancer","COPD","perioperative"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'health_maintenance', 'pending', NOW()),
('q-tax-pulm-025', 'clinical-vignette', 'PULM', 'hard', '{"question":"A physician is counseling a 48-year-old smoker about lung cancer screening. He has a 35 pack-year history (1.5 ppd x 23 years) and quit 2 years ago. What is the most appropriate screening recommendation based on current guidelines?","options":["A. Annual low-dose CT (LDCT) because of significant pack-year history","B. Annual LDCT because any smoking history warrants screening","C. No screening because he quit smoking >1 year ago","D. Annual chest X-ray surveillance"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"Current USPSTF (2021) and NCCN guidelines recommend annual LDCT screening for individuals aged 50-80 with 20+ pack-year history AND current smokers or those who quit <15 years ago. This patient quit 2 years ago and has 35 pack-years, so he falls within the eligibility window. At age 48, he is slightly under the typical starting age of 50, but his significant pack-year burden and recent cessation make him a candidate for screening discussions. Annual LDCT screening is appropriate for his risk profile and recent smoking history.","conditionName":"Lung Cancer Prevention","system":"PULM","subcategory":"Health Maintenance","tags":["PULM","screening","smoking-cessation","lung-cancer-prevention"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'health_maintenance', 'pending', NOW());
